import{mountShell}from'../shared/shell.js?v=0.3.0';import{attachCardDrag}from'../shared/drag.js';import{escapeHtml as e,readStore,writeStore,downloadText}from'../shared/utils.js';import{TEAMS,STYLES,create,validate,evaluate,assign,respond,run,policyComparison}from'./engine.js';mountShell({active:'local'});const app=document.querySelector('#app'),KEY='thinking-lab:local:v1';const saved=readStore(KEY,null);let s=saved?.s||saved||create(),past=[],baseline=saved?.baseline||null,message='',destroy=()=>{};try{validate(s);if(baseline)validate(baseline);}catch{s=create();baseline=null;}function save(){writeStore(KEY,{s,baseline});}const f=v=>v.toFixed(1);function change(next,text){past.push(structuredClone(s));past=past.slice(-30);s=validate(next);save();message=text;render();}function render(){destroy();const r=evaluate(s),b=baseline?evaluate({...baseline,pressure:s.pressure,weights:s.weights}):null;app.innerHTML=`<section class="surface"><div class="fields"><div class="field"><label for="reward">Weight of shared outcome in each team’s reward <output>${Math.round(s.reward*100)}%</output></label><input id="reward" type="range" min="0" max="100" step="10" value="${s.reward*100}"><p>The rest of the reward comes from that team’s own result.</p></div><div class="field"><label for="pressure">Strength of cross-team effects <output>${f(s.pressure)}×</output></label><input id="pressure" type="range" min="0" max="2" step="0.1" value="${s.pressure}"><p>Zero disconnects the external effects without changing each action’s direct benefit.</p></div></div><div class="toolbar"><button class="primary" id="respond">Each team chooses its next action</button><button id="run">Run until stable or cycling</button><button id="pin">Pin these actions</button><button id="undo" ${!past.length?'disabled':''}>Undo</button><button id="reset">Reset</button></div><p class="status" role="status">${e(message||'Drag a team to a different action style, or use its selector. A response round makes simultaneous choices from the current state.')}</p></section><section class="metrics"><div class="metric"><span>Shared weighted outcome</span><strong>${f(r.global)}</strong><small>${b?`${f(r.global-b.global)} vs pinned actions`:'Illustrative common score'}</small></div>${TEAMS.slice(0,3).map(t=>`<div class="metric"><span>${t.name} outcome</span><strong>${f(r.outcomes[t.id])}</strong><small>Reward ${f(r.rewards[t.id])}</small></div>`).join('')}</section><div class="team-board">${STYLES.map((label,index)=>`<section class="action-lane" data-drop-id="${index}"><h2>${label}</h2><p class="hint">${['Maximise the direct contribution to this team’s metric.','Accept a moderate direct benefit with fewer side effects.','Give up direct benefit, changing what other teams can do.'][index]}</p>${TEAMS.filter(t=>s.actions[t.id]===index).map(t=>`<article class="team-card" data-drag-id="${t.id}"><button class="team-handle" data-drag-handle aria-label="Drag ${t.name}; use selector below for keyboard">${t.name}</button><span class="team-metric">Objective: ${t.metric}</span><div class="team-numbers"><strong>${f(r.outcomes[t.id])}</strong><span>outcome · ${f(r.rewards[t.id])} reward</span></div><label for="action-${t.id}">Action</label><select id="action-${t.id}" data-team="${t.id}">${t.actions.map((a,i)=>`<option value="${i}" ${index===i?'selected':''}>${a}</option>`).join('')}</select></article>`).join('')||'<div class="empty-lane">Drop a team here.</div>'}</section>`).join('')}</div><div class="split"><section class="surface"><h2>Who benefits? Who absorbs the effect?</h2><div class="flow-list">${r.flows.map(flow=>`<div><span>${TEAMS.find(t=>t.id===flow.from).name} → ${TEAMS.find(t=>t.id===flow.to).name}</span><strong class="${flow.value<0?'bad':'good'}">${flow.value>0?'+':''}${f(flow.value)}</strong></div>`).join('')||'<p>No cross-team effects from these actions.</p>'}</div><p>Support outcome: <strong>${f(r.outcomes.support)}</strong> · reward ${f(r.rewards.support)}.</p></section><section class="surface"><h2>Compare reward rules</h2><p>Both begin with balanced actions and share the same coupling and outcome weights. Each team chooses the action with the highest next-round reward.</p><div class="table-scroll"><table><thead><tr><th>Reward</th><th>Shared outcome</th><th>Trajectory</th></tr></thead><tbody>${policyComparison(s).map(c=>`<tr><td>${c.reward?'Entirely shared':'Entirely own'}</td><td>${f(c.result.global)}</td><td>${c.history.length-1} rounds · ${c.status}</td></tr>`).join('')}</tbody></table></div><details><summary>Whose outcome counts most?</summary>${TEAMS.map(t=>`<div class="field"><label for="weight-${t.id}">${t.name} <output>${f(s.weights[t.id])}×</output></label><input id="weight-${t.id}" data-weight="${t.id}" type="range" min="0.5" max="3" step="0.5" value="${s.weights[t.id]}"></div>`).join('')}</details></section></div><details><summary>Mechanism and limits</summary><p>Each team starts at 50 and receives 9, 4 or −2 direct points from its three actions. Its action can add or subtract points elsewhere; negative effects are scaled by the receiving action’s exposure factor. The common outcome is a weighted mean. Reward mixes own outcome with that mean.</p><p>Best-response rounds are simultaneous, myopic and deterministic; ties keep the current action. Cycle detection stops repeated states. These illustrative payoff choices make externalities inspectable, not empirical measurements of incentives. Teams have no bargaining, learning or hidden information.</p><div class="table-scroll"><table><thead><tr><th>Team / action</th><th>Direct points</th><th>Effects before coupling/exposure</th></tr></thead><tbody>${TEAMS.flatMap(t=>t.actions.map((a,i)=>`<tr><td>${t.name}: ${a}</td><td>${[9,4,-2][i]}</td><td>${Object.entries(t.out[i]).map(([id,v])=>`${id} ${v>0?'+':''}${v}`).join('; ')||'None'}; receiver exposure ${t.buffer[i]}</td></tr>`)).join('')}</tbody></table></div></details><p class="local-note">Your current arrangement saves in this browser. Pinning holds actions; comparison shares current coupling and weights.</p>`;bind();destroy=attachCardDrag({root:app,onDrop:({itemId,dropId})=>change(assign(s,itemId,+dropId),'Team action changed. Follow its effects across the boundary.')});}
function bind(){for(const id of['reward','pressure'])document.querySelector('#'+id).onchange=ev=>{const v=+ev.target.value;change({...s,[id]:id==='reward'?v/100:v},'Reward or coupling assumption changed. Choose a response to let teams react.');};app.querySelectorAll('[data-team]').forEach(el=>el.onchange=()=>change(assign(s,el.dataset.team,+el.value),'Action changed.'));app.querySelectorAll('[data-weight]').forEach(el=>el.onchange=()=>change({...s,weights:{...s.weights,[el.dataset.weight]:+el.value}},'Shared outcome weights changed.'));document.querySelector('#respond').onclick=()=>change(respond(s),'One simultaneous response round completed.');document.querySelector('#run').onclick=()=>{const r=run(s);change(r.state,`${r.history.length-1} response rounds: ${r.status}.`);};document.querySelector('#pin').onclick=()=>{baseline=structuredClone(s);message='Actions pinned. Move a team to compare.';save();render();};document.querySelector('#undo').onclick=()=>{if(past.length){s=past.pop();save();render();}};document.querySelector('#reset').onclick=()=>change(create(),'Initial actions restored.');}document.querySelector('#export').onclick=()=>downloadText('local-outcomes.md',`# Local wins, collective losses\n\nShared weighted outcome: ${f(evaluate(s).global)}. Own/shared reward mix: ${Math.round(s.reward*100)}% shared.\n\n\`\`\`json\n${JSON.stringify({state:s,outcomes:evaluate(s),baseline},null,2)}\n\`\`\`\n\nFictional one-period payoffs and myopic simultaneous responses; no empirical prediction.\n`,'text/markdown');render();
